/** StudyGoal database table schema */CREATE TABLE IF NOT EXISTS study_goals (  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),  user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,  subject_id UUID NOT NULL REFERENCES subjects(id) ON DELETE CASCADE,  target_hours_per_week INTEGER NOT NULL CHECK (target_hours_per_week > 0),  current_hours INTEGER NOT NULL DEFAULT 0,  deadline TIMESTAMP WITH TIME ZONE NOT NULL,  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),  updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),  deleted_at TIMESTAMP WITH TIME ZONE,  UNIQUE(user_id, subject_id));CREATE INDEX idx_study_goals_user_id ON study_goals(user_id);CREATE INDEX idx_study_goals_subject_id ON study_goals(subject_id);CREATE INDEX idx_study_goals_deadline ON study_goals(deadline);COMMENT ON TABLE study_goals IS "Weekly study goals for subjects";COMMENT ON COLUMN study_goals.target_hours_per_week IS "Target hours per week";COMMENT ON COLUMN study_goals.current_hours IS "Current accumulated hours";COMMENT ON COLUMN study_goals.deadline IS "Goal deadline";
